7	/**
8	 * @fileoverview Input blocker utility for browser agent.
9	 *
10	 * Injects a transparent overlay that captures all user input events
11	 * and displays an informational banner during automation.
12	 *
13	 * The overlay is PERSISTENT — it stays in the DOM for the entire
14	 * browser agent session.  To allow CDP tool calls to interact with
15	 * page elements, we temporarily set `pointer-events: none` on the
16	 * overlay (via {@link suspendInputBlocker}) which makes it invisible
17	 * to hit-testing / interactability checks without any DOM mutation
18	 * or visual change.  After the tool call, {@link resumeInputBlocker}
19	 * restores `pointer-events: auto`.
20	 *
21	 * IMPORTANT: chrome-devtools-mcp's evaluate_script tool expects:
22	 *   { function: "() => { ... }" }
23	 * It takes a function declaration string, NOT raw code.
24	 * The parameter name is "function", not "code" or "expression".
25	 */
26	
27	import type { BrowserManager } from './browserManager.js';
28	import { debugLogger } from '../../utils/debugLogger.js';
29	
30	/**
31	 * JavaScript function to inject the input blocker overlay.
32	 * This blocks all user input events while allowing CDP commands to work normally.
33	 *
34	 * Must be a function declaration (NOT an IIFE) because evaluate_script
35	 * evaluates it via Puppeteer's page.evaluate().
36	 */
37	const INPUT_BLOCKER_FUNCTION = `() => {
38	  // If the blocker already exists, just ensure it's active and return.
39	  // This makes re-injection after potentially-navigating tools near-free
40	  // when the page didn't actually navigate (most clicks don't navigate).
41	  var existing = document.getElementById('__gemini_input_blocker');
42	  if (existing) {
43	    existing.style.pointerEvents = 'auto';
44	    return;
45	  }
46	
47	  const blocker = document.createElement('div');
48	  blocker.id = '__gemini_input_blocker';
49	  blocker.setAttribute('aria-hidden', 'true');
50	  blocker.setAttribute('role', 'presentation');
51	  blocker.style.cssText = [
52	    'position: fixed',
53	    'inset: 0',
54	    'z-index: 2147483646',
55	    'cursor: not-allowed',
56	    'background: transparent',
57	  ].join('; ');
58	
59	  // Block all input events on the overlay itself
60	  var blockEvent = function(e) {
61	    e.preventDefault();
62	    e.stopPropagation();
63	    e.stopImmediatePropagation();
64	  };
65	
66	  var events = [
67	    'click', 'mousedown', 'mouseup', 'keydown', 'keyup',
68	    'keypress', 'touchstart', 'touchend', 'touchmove', 'wheel',
69	    'contextmenu', 'dblclick', 'pointerdown', 'pointerup', 'pointermove',
70	  ];
71	  for (var i = 0; i < events.length; i++) {
72	    blocker.addEventListener(events[i], blockEvent, { capture: true });
73	  }
74	
75	  // Capsule-shaped floating pill at bottom center
76	  var pill = document.createElement('div');
77	  pill.style.cssText = [
78	    'position: fixed',
79	    'bottom: 20px',
80	    'left: 50%',
81	    'transform: translateX(-50%) translateY(20px)',
82	    'display: flex',
83	    'align-items: center',
84	    'gap: 10px',
85	    'padding: 10px 20px',
86	    'background: rgba(24, 24, 27, 0.88)',
87	    'color: #fff',
88	    'font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
89	    'font-size: 13px',
90	    'line-height: 1',
91	    'border-radius: 999px',
92	    'z-index: 2147483647',
93	    'backdrop-filter: blur(16px)',
94	    '-webkit-backdrop-filter: blur(16px)',
95	    'border: 1px solid rgba(255, 255, 255, 0.08)',
96	    'box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.05)',
97	    'opacity: 0',
98	    'transition: opacity 0.4s ease, transform 0.4s ease',
99	    'white-space: nowrap',
100	    'user-select: none',
101	    'pointer-events: none',
102	  ].join('; ');
103	
104	  // Pulsing red dot
105	  var dot = document.createElement('span');
106	  dot.style.cssText = [
107	    'width: 10px',
108	    'height: 10px',
109	    'border-radius: 50%',
110	    'background: #ef4444',
111	    'display: inline-block',
112	    'flex-shrink: 0',
113	    'box-shadow: 0 0 6px rgba(239, 68, 68, 0.6)',
114	    'animation: __gemini_pulse 2s ease-in-out infinite',
115	  ].join('; ');
116	
117	  // Labels
118	  var label = document.createElement('span');
119	  label.style.cssText = 'font-weight: 600; letter-spacing: 0.01em;';
120	  label.textContent = 'Gemini CLI is controlling this browser';
121	
122	  var sep = document.createElement('span');
123	  sep.style.cssText = 'width: 1px; height: 14px; background: rgba(255,255,255,0.2); flex-shrink: 0;';
124	
125	  var sub = document.createElement('span');
126	  sub.style.cssText = 'color: rgba(255,255,255,0.55); font-size: 12px;';
127	  sub.textContent = 'Input disabled during automation';
128	
129	  pill.appendChild(dot);
130	  pill.appendChild(label);
131	  pill.appendChild(sep);
132	  pill.appendChild(sub);
133	
134	  // Inject @keyframes for the pulse animation
135	  var styleEl = document.createElement('style');
136	  styleEl.id = '__gemini_input_blocker_style';
137	  styleEl.textContent = '@keyframes __gemini_pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(0.85); } }';
138	  document.head.appendChild(styleEl);
139	
140	  blocker.appendChild(pill);
141	  var target = document.body || document.documentElement;
142	  if (target) {
143	    target.appendChild(blocker);
144	    // Trigger entrance animation
145	    requestAnimationFrame(function() {
146	      pill.style.opacity = '1';
147	      pill.style.transform = 'translateX(-50%) translateY(0)';
148	    });
149	  }
150	}`;
