152	/**
153	 * JavaScript function to remove the input blocker overlay entirely.
154	 * Used only during final cleanup.
155	 */
156	const REMOVE_BLOCKER_FUNCTION = `() => {
157	  var blocker = document.getElementById('__gemini_input_blocker');
158	  if (blocker) {
159	    blocker.remove();
160	  }
161	  var style = document.getElementById('__gemini_input_blocker_style');
162	  if (style) {
163	    style.remove();
164	  }
165	}`;
166	
167	/**
168	 * JavaScript to temporarily suspend the input blocker by setting
169	 * pointer-events to 'none'.  This makes the overlay invisible to
170	 * hit-testing so chrome-devtools-mcp's interactability checks pass
171	 * and CDP clicks fall through to page elements.
172	 *
173	 * The overlay DOM element stays in place — no visual change, no flickering.
174	 */
175	const SUSPEND_BLOCKER_FUNCTION = `() => {
176	  var blocker = document.getElementById('__gemini_input_blocker');
177	  if (blocker) {
178	    blocker.style.pointerEvents = 'none';
179	  }
180	}`;
181	
182	/**
183	 * JavaScript to resume the input blocker by restoring pointer-events
184	 * to 'auto'.  User clicks are blocked again.
185	 */
186	const RESUME_BLOCKER_FUNCTION = `() => {
187	  var blocker = document.getElementById('__gemini_input_blocker');
188	  if (blocker) {
189	    blocker.style.pointerEvents = 'auto';
190	  }
191	}`;
192	
193	/**
194	 * Injects the input blocker overlay into the current page.
195	 *
196	 * @param browserManager The browser manager to use for script execution
197	 * @returns Promise that resolves when the blocker is injected
198	 */
199	export async function injectInputBlocker(
200	  browserManager: BrowserManager,
201	  signal?: AbortSignal,
202	): Promise<void> {
203	  try {
204	    await browserManager.callTool(
205	      'evaluate_script',
206	      { function: INPUT_BLOCKER_FUNCTION },
207	      signal,
208	    );
209	    debugLogger.log('Input blocker injected successfully');
210	  } catch (error) {
211	    // Log but don't throw - input blocker is a UX enhancement, not critical functionality
212	    debugLogger.warn(
213	      'Failed to inject input blocker: ' +
214	        (error instanceof Error ? error.message : String(error)),
215	    );
216	  }
217	}
